import matplotlib.pyplot as plt
import numpy as np
from Bio import Align
import matplotlib.patches as patches

# Define sequences (extracted from the Sequence Catalog files)
sequences = {
    'Human_MMP2': '',
    'Mouse_MMP2': '',
    'Human_ADAM17': '',
    'Rat_ADAM17': '',
    'Human_MMP9_Full': '',
    'Human_MMP9_Catalytic': 'F' + '' # Phe107-Pro449
}
# Note: The catalytic sequence above is just a slice of the full for illustration in diagram. 
# In reality, it starts at index 106 (0-indexed) if Phe is 107.


def plot_alignment(seq1, seq2, name1, name2, title, filename):
    aligner = Align.PairwiseAligner()
    aligner.mode = 'global'
    alignments = aligner.align(seq1, seq2)
    alignment = alignments[0]
    
    # Get aligned sequences
    aln1 = alignment[0]
    aln2 = alignment[1]
    
    length = len(aln1)
    
    # Visualization setup
    fig, ax = plt.subplots(figsize=(15, 4))
    
    # Colors
    match_color = '#4CAF50'    # Green
    mismatch_color = '#F44336' # Red
    gap_color = '#9E9E9E'      # Grey
    
    chunk_size = 100
    rows = (length // chunk_size) + 1
    
    # Reset fig for multi-row if needed, but for now let's just do a single long strip or overview
    # Let's do an overview bar + a detailed zoom of first 100? 
    # Actually, let's do a "coverage" style plot.
    
    x = np.arange(length)
    y1 = np.ones(length) * 2
    y2 = np.ones(length) * 1
    
    matches = [a == b and a != '-' for a, b in zip(aln1, aln2)]
    mismatches = [a != b and a != '-' and b != '-' for a, b in zip(aln1, aln2)]
    gaps1 = [a == '-' for a in aln1]
    gaps2 = [b == '-' for b in aln2]
    
    # Draw bars
    for i in range(length):
        if aln1[i] == aln2[i] and aln1[i] != '-':
            color = match_color
        elif aln1[i] == '-' or aln2[i] == '-':
            color = gap_color
        else:
            color = mismatch_color
            
        ax.add_patch(patches.Rectangle((i, 0.5), 1, 2, color=color, alpha=0.8))

    ax.set_xlim(0, length)
    ax.set_ylim(0, 3)
    ax.set_yticks([1, 2])
    ax.set_yticklabels([name2, name1])
    ax.set_title(title)
    ax.set_xlabel("Sequence Position")
    
    # Add a legend
    from matplotlib.lines import Line2D
    legend_elements = [
        Line2D([0], [0], color=match_color, lw=4, label='Match'),
        Line2D([0], [0], color=mismatch_color, lw=4, label='Mismatch'),
        Line2D([0], [0], color=gap_color, lw=4, label='Gap')
    ]
    ax.legend(handles=legend_elements, loc='upper right')
    
    plt.tight_layout()
    plt.savefig(filename, dpi=300)
    plt.close()

# Generate plots
plot_alignment(sequences['Human_MMP2'], sequences['Mouse_MMP2'], 'Human MMP2', 'Mouse MMP2', 'Sequence Alignment: Human vs Mouse MMP2', 'MMP2_Alignment.png')
plot_alignment(sequences['Human_ADAM17'], sequences['Rat_ADAM17'], 'Human ADAM17', 'Rat ADAM17', 'Sequence Alignment: Human vs Rat ADAM17', 'ADAM17_Alignment.png')
plot_alignment(sequences['Human_MMP9_Full'], sequences['Human_MMP9_Catalytic'], 'MMP9 Full', 'MMP9 Catalytic', 'Sequence Comparison: MMP9 Full-Length vs Catalytic Domain', 'MMP9_Comparison.png')

print("Alignment diagrams generated: MMP2_Alignment.png, ADAM17_Alignment.png, and MMP9_Comparison.png")
